KG42.register("rules-256884c42f73e72e0119b497",{"id":"28-multiclass_prosumer_preferences::v141-c-R005","paper":"28-multiclass_prosumer_preferences","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"Submitted prosumer net energy demands provide information for adjustment of the energy-class price signals. Scope: Distribution-network multiclass P2P market; iterative price-directed optimisation over the time horizon. The platform's update of energy-class allocations supplied to the prosumers precedes its dual-price update. Scope: Within each iteration of the distributed multiclass market algorithm. The platform agent performs the dual-price updates used for price-signal coordination. Scope: Distribution-network multiclass P2P market; each iteration of distributed price-directed optimisation. The dual-price adjustment rule increases the price signal in the excess-demand case. Scope: Walrasian-auction interpretation of ADMM dual-price coordination in the proposed multiclass market. Condition: Excess demand. The dual-price adjustment rule decreases the price signal in the excess-supply case. Scope: Walrasian-auction interpretation of ADMM dual-price coordination in the proposed multiclass market. Condition: Excess supply.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.local","coordination.local_operator","coordination.price_signal"],"E":[{"edge_id":"v141-c-R005-E001","source":"bidding.demand","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E08","v141-b-g02-e023"]},{"edge_id":"v141-c-R005-E002","source":"clearing.local","target":"coordination.price_signal","type":"precedes","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g02-e024","v141-b-g02-e025"]},{"edge_id":"v141-c-R005-E003","source":"coordination.local_operator","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C003"],"evidence_ids":["v141-b-g02-e025"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Distribution-network multiclass P2P market; each iteration of distributed price-directed optimisation. | Distribution-network multiclass P2P market; iterative price-directed optimisation over the time horizon. | Walrasian-auction interpretation of ADMM dual-price coordination in the proposed multiclass market. | Within each iteration of the distributed multiclass market algorithm.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g02-e019","v141-b-g02-e023","v141-b-g02-e024","v141-b-g02-e025"]},"x":[{"variable_id":"v141-c-R005-x001","symbol":"\\nu_k^{(t)}(\\kappa)","meaning":"Dual price variable interpreted as the price of non-grid energy class k in the distribution network at interval t in iteration kappa, updated by the platform agent.","kind":"operational","domain":"Unspecified in source; price signal updated by the affine rule (23).","unit":null,"indices":["k","t","\\kappa"],"evidence_ids":["v141-b-g02-e020","v141-b-g02-e025"]},{"variable_id":"v141-c-R005-x002","symbol":"\\nu_g^{(t)}(\\kappa)","meaning":"Dual price variable interpreted as the grid-energy-class price in the distribution network at interval t in iteration kappa, updated by the platform agent.","kind":"operational","domain":"Unspecified in source; price signal updated by the affine rule (23).","unit":null,"indices":["t","\\kappa"],"evidence_ids":["v141-b-g02-e020","v141-b-g02-e025"]},{"variable_id":"v141-c-R005-x003","symbol":"\\tilde{x}_{ik}^{(t)}(\\kappa)","meaning":"Prosumer i's reported net power demand for non-grid energy class k at interval t in iteration kappa, sent to the platform agent.","kind":"operational","domain":"Unspecified in source; net power term in (23), sign unrestricted.","unit":null,"indices":["i","k","t","\\kappa"],"evidence_ids":["v141-b-g02-e023","v141-b-g02-e025"]},{"variable_id":"v141-c-R005-x004","symbol":"\\tilde{x}_{ig}^{(t)}(\\kappa)","meaning":"Prosumer i's reported net power demand for grid energy at interval t in iteration kappa, sent to the platform agent.","kind":"operational","domain":"Unspecified in source; net power term in (23), sign unrestricted.","unit":null,"indices":["i","t","\\kappa"],"evidence_ids":["v141-b-g02-e023","v141-b-g02-e025"]},{"variable_id":"v141-c-R005-x005","symbol":"x_{ik}^{(t)}(\\kappa)","meaning":"Net power of non-grid energy class k allocated/supplied to prosumer i at interval t in iteration kappa by the platform agent.","kind":"operational","domain":"Unspecified in source; net power variable in the platform subproblem (22) and dual update (23).","unit":null,"indices":["i","k","t","\\kappa"],"evidence_ids":["v141-b-g02-e024","v141-b-g02-e025"]},{"variable_id":"v141-c-R005-x006","symbol":"x_{ig}^{(t)}(\\kappa)","meaning":"Net grid energy allocated/supplied to prosumer i at interval t in iteration kappa by the platform agent.","kind":"operational","domain":"Unspecified in source; net power variable in the platform subproblem (22) and dual update (23).","unit":null,"indices":["i","t","\\kappa"],"evidence_ids":["v141-b-g02-e024","v141-b-g02-e025"]}],"theta":[{"parameter_id":"v141-c-R005-theta001","symbol":"\\rho","meaning":"ADMM step size, a positive penalty and dual-price update coefficient used by the platform agent in (23).","value":{"kind":"symbolic","number_value":null,"text_value":"\\rho>0"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e025"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Submitted prosumer net energy demands provide information for adjustment of the energy-class price signals. Scope: Distribution-network multiclass P2P market; iterative price-directed optimisation over the time horizon.","expression":"\\nu_g^{(t)}(\\kappa)=\\nu_g^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\\right),\\quad t\\in\\mathcal{T};\\qquad \\nu_k^{(t)}(\\kappa)=\\nu_k^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\\right),\\quad k\\in\\mathcal{K},\\ t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":["v141-c-R005-x001","v141-c-R005-x002","v141-c-R005-x003","v141-c-R005-x004","v141-c-R005-x005","v141-c-R005-x006"],"parameter_refs":["v141-c-R005-theta001"],"evidence_ids":["v141-b-g01-E08","v141-b-g02-e023","v141-b-g02-e025"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"The platform's update of energy-class allocations supplied to the prosumers precedes its dual-price update. Scope: Within each iteration of the distributed multiclass market algorithm.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e024","v141-b-g02-e025"]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"The platform agent performs the dual-price updates used for price-signal coordination. Scope: Distribution-network multiclass P2P market; each iteration of distributed price-directed optimisation.","expression":"\\nu_g^{(t)}(\\kappa)=\\nu_g^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\\right),\\quad t\\in\\mathcal{T};\\qquad \\nu_k^{(t)}(\\kappa)=\\nu_k^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\\right),\\quad k\\in\\mathcal{K},\\ t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","coordination.price_signal"],"variable_refs":["v141-c-R005-x001","v141-c-R005-x002","v141-c-R005-x003","v141-c-R005-x004","v141-c-R005-x005","v141-c-R005-x006"],"parameter_refs":["v141-c-R005-theta001"],"evidence_ids":["v141-b-g02-e025"]},{"constraint_id":"v141-c-R005-C004","kind":"procedural","role":"core","statement":"The dual-price adjustment rule increases the price signal in the excess-demand case. Scope: Walrasian-auction interpretation of ADMM dual-price coordination in the proposed multiclass market. Condition: Excess demand.","expression":"\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)>0,\\ \\rho>0\\ \\Longrightarrow\\ \\nu_g^{(t)}(\\kappa)>\\nu_g^{(t)}(\\kappa-1);\\qquad \\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)>0,\\ \\rho>0\\ \\Longrightarrow\\ \\nu_k^{(t)}(\\kappa)>\\nu_k^{(t)}(\\kappa-1).","formalization_origin":"equivalent_translation","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R005-x001","v141-c-R005-x002","v141-c-R005-x003","v141-c-R005-x004","v141-c-R005-x005","v141-c-R005-x006"],"parameter_refs":["v141-c-R005-theta001"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e025"]},{"constraint_id":"v141-c-R005-C005","kind":"procedural","role":"core","statement":"The dual-price adjustment rule decreases the price signal in the excess-supply case. Scope: Walrasian-auction interpretation of ADMM dual-price coordination in the proposed multiclass market. Condition: Excess supply.","expression":"\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\u003c0,\\ \\rho>0\\ \\Longrightarrow\\ \\nu_g^{(t)}(\\kappa)\u003c\\nu_g^{(t)}(\\kappa-1);\\qquad \\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\u003c0,\\ \\rho>0\\ \\Longrightarrow\\ \\nu_k^{(t)}(\\kappa)\u003c\\nu_k^{(t)}(\\kappa-1).","formalization_origin":"equivalent_translation","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R005-x001","v141-c-R005-x002","v141-c-R005-x003","v141-c-R005-x004","v141-c-R005-x005","v141-c-R005-x006"],"parameter_refs":["v141-c-R005-theta001"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e025"]}],"pi":[{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-96285c344a-p03-c1r2__v141-a-M01-coordination","page":3,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"Fig. 2. A block diagram of the proposed P2P energy market platform. Distributed price-directed optim","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Distributed price-directed optimisation parallelises the multi-class energy management problem. At each wholesale market trading interval, the prosumers solve local optimisation sub-problems to schedule their renewable sources and battery energy storage systems, considering their generation and load predictions and the price of each class of energy. The platform agent adjusts the energy class prices, considering the prosumer energy demands, the wholesale energy price, wholesale price predictions and expected losses. Iteratively, the prosumers and platform agent reach agreement on a schedule of social welfare maximising power flows."},{"evidence_id":"v141-b-g02-e019","location":{"location_id":"src-96285c344a-p05-c2r3__v141-a-M01-coordination","page":5,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"uses iterative local optimisation and dual price adjustments [41]. The dual price adjustments can be","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"ADMM is a distributed convex optimisation method, which uses iterative local optimisation and dual price adjustments [41]. The dual price adjustments can be interpreted as the tâtonnement process of a Walrasian auction i.e., a competitive market mechanism, where the prices of goods are increased in the case of excess demand and decreased in the case of excess supply, to achieve equilibrium at a set of market clearing prices. ADMM provides convergence even if the local sub-problems are constrained [41]."},{"evidence_id":"v141-b-g02-e023","location":{"location_id":"src-96285c344a-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"k∈K ρ 2 + z(t)ik (κ)−x(t)ik (κ−1)−y(t)ik (κ)−b(t)ik (κ) . 2 ρ > 0 in the penalty terms is the ADMM s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"2) The prosumers calculate their net power demands for each energy class over the time horizon, and send this information to the platform agent, \\[ \\tilde{x}_{ig}^{(t)}(\\kappa)=z_{ig}^{(t)}(\\kappa)-y_{ig}^{(t)}(\\kappa)-b_{ig}^{(t)}(\\kappa),\\quad t\\in\\mathcal T, \\] \\[ \\tilde{x}_{ik}^{(t)}(\\kappa)=z_{ik}^{(t)}(\\kappa)-y_{ik}^{(t)}(\\kappa)-b_{ik}^{(t)}(\\kappa),\\quad k\\in\\mathcal K,\\ t\\in\\mathcal T. \\]"},{"evidence_id":"v141-b-g02-e024","location":{"location_id":"src-96285c344a-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"g an (g ( t ) (κ),x(i kt ) (κ),x(i gt ) (κ)|k∈K,i∈N) R subject to (3), (4), (Power Flow Const.) ‘g L","equation_id":"(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"3) The platform agent, in parallel for each interval of the time horizon, \\(t\\in\\mathcal T\\), updates the net power of each energy class supplied to each prosumer and the power imported from the grid, for the current iteration, \\(\\kappa\\), by solving, \\[ \\underset{(g^{(t)}(\\kappa),x_{ik}^{(t)}(\\kappa),x_{ig}^{(t)}(\\kappa)|k\\in\\mathcal K,i\\in\\mathcal N)}{\\text{minimise}}\\quad L_g^{(t)} \\] subject to (3),(4), (Power Flow Const.) \\[ \\begin{aligned} L_g^{(t)}={}&f_g^{(t)}+\\sum_{i\\in\\mathcal N}\\left[ \\nu_g^{(t)}(\\kappa-1)\\left(\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\\right) +\\frac{\\rho}{2}\\left(\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\\right)^2 \\right. \\\\ &\\left. +\\sum_{k\\in\\mathcal K}\\left( \\nu_k^{(t)}(\\kappa-1)\\left(\\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\\right) +\\frac{\\rho}{2}\\left(\\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\\right)^2 \\right) \\right]. \\end{aligned} \\tag{22} \\]"},{"evidence_id":"v141-b-g02-e025","location":{"location_id":"src-96285c344a-p06-c1r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"power balance constraints (3), (4). This means that only a single sy dual price is needed for each c","equation_id":"(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"4) The platform agent then updates the dual prices. For a particular class of energy \\(k\\in\\mathcal K\\) and time interval \\(t\\in\\mathcal T\\), the prosumer coupling constraints (5), (6), will have the same dual price for all \\(i\\in\\mathcal N\\), since relaxations are interchangeable through the power balance constraints (3), (4). This means that only a single dual price is needed for each class of energy at each interval of the time horizon, and the platform agent can update the prices using the coupling constraint mismatch for any prosumer \\(i\\in\\mathcal N\\), \\[ \\nu_g^{(t)}(\\kappa)=\\nu_g^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ig}^{(t)}(\\kappa)-x_{ig}^{(t)}(\\kappa)\\right),\\quad t\\in\\mathcal T, \\] \\[ \\nu_k^{(t)}(\\kappa)=\\nu_k^{(t)}(\\kappa-1)+\\rho\\left(\\tilde{x}_{ik}^{(t)}(\\kappa)-x_{ik}^{(t)}(\\kappa)\\right),\\quad k\\in\\mathcal K,\\ t\\in\\mathcal T. \\tag{23} \\]"},{"evidence_id":"v141-b-g02-e020","location":{"location_id":"src-96285c344a-p05-c2r3__v141-a-M01-coordination","page":5,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"uses iterative local optimisation and dual price adjustments [41]. The dual price adjustments can be","equation_id":"(20)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"At each wholesale electricity market trading interval, the following distributed mechanism is used to solve the multi-class energy management problem (20). The platform agent initialises the net power of each energy class assigned to the prosumers over the time horizon, \\(x_{ig}^{(t)}(0), x_{ik}^{(t)}(0), k\\in\\mathcal K, t\\in\\mathcal T\\), as well as dual price variables, \\(\\nu_g^{(t)}(0), \\nu_k^{(t)}(0), k\\in\\mathcal K, t\\in\\mathcal T\\), which can be interpreted as the prices of each class of energy in the distribution network for each interval of the time horizon. These initial values are sent to the individual prosumers. Then, during each iteration \\(\\kappa\\): 1) In parallel, each prosumer, \\(i\\in\\mathcal N\\), updates its local decision variables for the current iteration, \\(\\kappa\\), by minimising an augmented Lagrangian, \\(L_i\\), subject to local constraints."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E08","quote":"The platform agent adjusts the energy class prices, considering the prosumer energy demands, the wholesale energy price, wholesale price predictions and expected losses."},{"evidence_id":"v141-b-g02-e023","quote":"2) The prosumers calculate their net power demands for each energy class over the time horizon, and send this information to the platform agent,"}],[{"evidence_id":"v141-b-g02-e024","quote":"updates the net power of each energy class supplied to each prosumer and the power imported from the grid, for the current iteration,"},{"evidence_id":"v141-b-g02-e025","quote":"4) The platform agent then updates the dual prices."}],[{"evidence_id":"v141-b-g02-e025","quote":"4) The platform agent then updates the dual prices."}],[{"evidence_id":"v141-b-g02-e019","quote":"where the prices of goods are increased in the case of excess demand and decreased in the case of excess supply"}],[{"evidence_id":"v141-b-g02-e019","quote":"where the prices of goods are increased in the case of excess demand and decreased in the case of excess supply"}]],"C2_formalization":{"graph_sha256":"c70d5005d5e503d69f255ee87a78c0c40d829fe84f32dd680967f6aa2da68f5d","applicability":"formalized","reason":"Partially formalized from equation (23): the platform-agent dual-price updates and the Walrasian excess-demand/excess-supply sign directions are represented using declared price and net-power variables. C001 is formalized by showing the reported net demand in the dual-price update. C002 remains a procedural precedence and is not forced into an equation. B evidence remains unreviewed; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R005-x001","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E003"],"rationale":"The non-grid dual price is the price signal object updated by the platform agent from reported demand; E001 links demand to the price signal and E003 links the local operator to the price signal."},{"object_id":"v141-c-R005-x002","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E003"],"rationale":"The grid-class dual price is part of the same platform-agent price signal; E001 links demand to price and E003 links the operator to price."},{"object_id":"v141-c-R005-x003","node_ids":["bidding.demand","coordination.price_signal"],"edge_ids":["v141-c-R005-E001"],"rationale":"Reported non-grid net demand is the demand-side information entering the price adjustment; E001 is the bidding.demand-to-price_signal edge."},{"object_id":"v141-c-R005-x004","node_ids":["bidding.demand","coordination.price_signal"],"edge_ids":["v141-c-R005-E001"],"rationale":"Reported grid net demand is the grid-class counterpart of the demand information entering the price adjustment; E001 is the bidding.demand-to-price_signal edge."},{"object_id":"v141-c-R005-x005","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R005-E002"],"rationale":"The platform-agent allocation of non-grid net power is the clearing quantity whose prior update precedes the dual-price update; E002 is the clearing.local-to-price_signal precedence edge."},{"object_id":"v141-c-R005-x006","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R005-E002"],"rationale":"The platform-agent allocation of grid net power is the grid-class counterpart whose prior update precedes the dual-price update; E002 is the clearing.local-to-price_signal precedence edge."},{"object_id":"v141-c-R005-theta001","node_ids":["coordination.local_operator","coordination.price_signal"],"edge_ids":["v141-c-R005-E003"],"rationale":"The positive ADMM step size rho is used by the platform agent in the dual-price update; E003 links coordination.local_operator to coordination.price_signal."},{"object_id":"v141-c-R005-C001","node_ids":["bidding.demand","coordination.price_signal"],"edge_ids":["v141-c-R005-E001"],"rationale":"The expression shows reported prosumer net demand inside the dual-price update, formalizing the demand-to-price information channel represented by E001."},{"object_id":"v141-c-R005-C003","node_ids":["coordination.local_operator","coordination.price_signal"],"edge_ids":["v141-c-R005-E003"],"rationale":"The expression is the platform-agent dual-price update equation (23), matching the local-operator-to-price-signal relation E003."},{"object_id":"v141-c-R005-C004","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"The positive-mismatch implication formalizes the excess-demand sign direction of the price signal; the mismatch uses reported demand (E001) and prior allocated net power (E002)."},{"object_id":"v141-c-R005-C005","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"The negative-mismatch implication formalizes the excess-supply sign direction of the price signal; the mismatch uses reported demand (E001) and prior allocated net power (E002)."}],"revision_requests":[]}},"quarantined_references":[]}});
